from playwright.sync_api import sync_playwright
with sync_playwright() as p:
 b=p.chromium.launch();g=b.new_page();g.goto('http://localhost:8080/');g.evaluate("async()=>{let m=await import('/fps-game.js');window.game=m.mountFPS(document.querySelector('#app'),{exercise:'third'})}");assert g.locator('#fpsSensitivity').count()==1;g.click('#fpsStart');g.keyboard.press('Space');a=g.evaluate('game.state.ammo');g.keyboard.down('r');g.wait_for_timeout(650);g.locator('#fpsCanvas').dispatch_event('mousedown',{'button':0});assert g.evaluate('game.state.ammo')==a;g.keyboard.up('r');g.locator('#fpsCanvas').dispatch_event('mousedown',{'button':0});assert g.evaluate('game.state.ammo')==a-1;g.evaluate('game.state.hits=[[{x:0,y:0},{x:0,y:0},{x:0,y:0}],[{x:0,y:0},{x:0,y:0},{x:0,y:0}]];game.state.entities.filter(e=>e.kind===\"target\").forEach(e=>e.hp=0)');g.wait_for_timeout(2000);assert g.evaluate('game.state.wave')==2;print('PASS sensitivity, hold inspection fire lock, third auto new pair');b.close()
